 const cloud=useFirebase();const[demo,setDemo]=useState(readDemo);const[role,setRole]=useState('teacher');const[page,setPage]=useState('rewards');const[classId,setClassId]=useState('c1');const[studentId,setStudentId]=useState('s1');const[selected,setSelected]=useState([]);const[toast,setToast]=useState(null);const[busy,setBusy]=useState(false);const[modal,setModal]=useState(null);const[search,setSearch]=useState('');const[amount,setAmount]=useState(3);const[reason,setReason]=useState(reasons[0]);const[newName,setNewName]=useState('');const[newGrade,setNewGrade]=useState(GRADES[0]);
