 async function act(action,opts={}){if(busy)return false;setBusy(true);try{let result;if(configured)result=await cloud.action(action);else{const actor={role:currentRole,studentId:activeStudent?.id,name:currentRole==='teacher'?'示範老師':activeStudent?.name,verifiedGame:opts.verifiedGame};const next=demoAction(data,{...action,requestId:uid()},actor);setDemo(next);result=next}if(opts.message)notify(opts.message);return result}catch(e){notify(e.message?.replace(/^.*?: /,''),true);return false}finally{setBusy(false)}}
 function switchRole(next){setRole(next);setPage(next==='teacher'?'rewards':'claw');setSelected([])}
 useEffect(()=>{if(configured&&currentRole==='student')setPage('claw')},[currentRole]);
